INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13701, 'Psalms 50:21', 'Psalms', 50, 21, '&nbsp;ستا په دې کارونو زۀ چپ پاتې شوم، زۀ دې هم د خپل ځان په شان وګڼلم. خو زۀ دې اوس رټمه او په تا اِلزام لګوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13702, 'Psalms 50:22', 'Psalms', 50, 22, '&nbsp;ما ته غوږ شئ چا چې زۀ هېر کړے يم هغوئ ټول دې توبه ګار شى، زۀ به مو ټوټې کړم او هيڅ څوک به نۀ وى چې ستاسو مددګار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13703, 'Psalms 50:23', 'Psalms', 50, 23, '&nbsp;څوک هم چې د شُکر ګزارۍ قربانى کوى نو زما احترام کوى. څوک چې هم په صحيح لار روان وى، نو زۀ به ورته د خُدائ خلاصون څرګند کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13704, 'Psalms 51:1', 'Psalms', 51, 1, '&nbsp;د خپل رحم په مطابق دې په ما مهربان شه خُدايه، او د خپلې ازلى مينې په وجه دې په ما رحم وکړه، د خپل لوئ رحم په مطابق دې زما ګناهونه ختم کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13705, 'Psalms 51:2', 'Psalms', 51, 2, '&nbsp;ټول ګناهونه زما ووينځه، او د ګناه نه مې پاک او صفا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13706, 'Psalms 51:3', 'Psalms', 51, 3, '&nbsp;زۀ په خپل شرارت باندې پوهه يم، زۀ په خپلو بدو ټول عمر فکرمند يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13707, 'Psalms 51:4', 'Psalms', 51, 4, '&nbsp;ستا او يواځې ستا خلاف مې ګناه کړې ده زۀ ګناه ګار يم، ما هغه کار کړے دے کوم چې ستا په نظر کښې بد دے. تۀ دې په خپلو خبرو کښې رښتينې وګرځې، او ستا عدالت زما په حق کښې ټيک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13708, 'Psalms 51:5', 'Psalms', 51, 5, '&nbsp;ګوره، زۀ د ازل نه بدعمله يم، د مور د ګېډې نه زۀ بلکل ګناه ګار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13709, 'Psalms 51:6', 'Psalms', 51, 6, '&nbsp;نو چې اخلاص او صداقت رانه غواړې، نو تۀ په خپله زما زړۀ ته پوهه راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13710, 'Psalms 51:7', 'Psalms', 51, 7, '&nbsp;تۀ زما ګناه ووينځه نو زۀ به صفا شم، تۀ مې ووينځه نو زۀ به هم د واورې نه زيات سپين شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13711, 'Psalms 51:8', 'Psalms', 51, 8, '&nbsp;ما ته د خندا او خوشحالۍ خبرې وکړه، کوم هډُوکى چې تا ما ته مات کړى وُو اوس دې خوشحالى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13712, 'Psalms 51:9', 'Psalms', 51, 9, '&nbsp;زما د ګناهونو نه مخ واړوه، زما بدۍ ټولې صفا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13713, 'Psalms 51:10', 'Psalms', 51, 10, '&nbsp;پاکه خُدايه صفا زړۀ ما له راکړه، په ما کښې تازه او وفادار روح واچوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13714, 'Psalms 51:11', 'Psalms', 51, 11, '&nbsp;ما تۀ د خپل حضور نه مۀ شړه، خپل مقدس روح زما نه مۀ بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13715, 'Psalms 51:12', 'Psalms', 51, 12, '&nbsp;ستا د خلاصون خوشحالى بيا يو وارې راکړه. او زما روح ستا تابعدارۍ ته مائل کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13716, 'Psalms 51:13', 'Psalms', 51, 13, '&nbsp;نو زۀ به نافرمانو ته وښايم ستا حُکمونه، نو ګناه ګار به يو ځل بيا تا ته راوګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13717, 'Psalms 51:14', 'Psalms', 51, 14, '&nbsp;اے خُدايه، ما د وينې تويولو د جرم نه معاف کړه، نو بيا به زۀ په خوشحالۍ سره ستا د معافۍ سرود بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13718, 'Psalms 51:15', 'Psalms', 51, 15, '&nbsp;اے مالِکه خُدايه زما شونډې خلاصې کړه، او زۀ به په خپله خولۀ ستا ثناء صِفت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13719, 'Psalms 51:16', 'Psalms', 51, 16, '&nbsp;چې زۀ يې تا ته وړاندې کړم تۀ قربانى نۀ غواړې، او نۀ په سوزېدونکو قربانو تۀ خوشحالېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13720, 'Psalms 51:17', 'Psalms', 51, 17, '&nbsp;پاکه خُدايه تا ته د عاجز او مات روحونو خوښه ده قربانى، تۀ غمژن او توبه ګار زړۀ سپک نۀ ګڼې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13721, 'Psalms 51:18', 'Psalms', 51, 18, '&nbsp;پاکه خُدايه د صيون ښار مدد وکړه مهربان شه، د يروشلم دېوالونه جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13722, 'Psalms 51:19', 'Psalms', 51, 19, '&nbsp;نو هلته به تا ته رښتينې قربانۍ پېش شى او ټولې سوزېدونکې نذرانې چې تۀ پرې خوشحاله شې، او ستا په قربان‌ګاه باندې به غوَيان تا ته وړاندې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13723, 'Psalms 52:1', 'Psalms', 52, 1, '&nbsp;تۀ ولې په خپلو بدو فخر کوې زورَوره؟ ولې تۀ خبر نۀ يې چې د خُدائ مينه وى د تل دپاره؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13724, 'Psalms 52:2', 'Psalms', 52, 2, '&nbsp;ژبه دې د نورو خلقو د تباهۍ په لټون کښې ده، او لکه د تېرې چړې په شان ده او ټګى ماره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13725, 'Psalms 52:3', 'Psalms', 52, 3, '&nbsp;تاسو بدۍ سره د نېکۍ نه زياته مينه کوئ، تاسو د ټګۍ سره د رښتيا نه زياته مينه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13726, 'Psalms 52:4', 'Psalms', 52, 4, '&nbsp;تاسو دا خوښوئ چې په خپلو خبرو نور خلق تباه کړئ، تاسو دروغژن يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13727, 'Psalms 52:5', 'Psalms', 52, 5, '&nbsp;خو خُدائ به تاسو د تل دپاره تباه کړى. د کور نه به دې راونيسى او د ژوندو د دُنيا نه به دې بېخ ختم کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13728, 'Psalms 52:6', 'Psalms', 52, 6, '&nbsp;صادقان چې دا وګورى نو وبه يريږى، دوئ به هغۀ پورې خاندى او وبه وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13729, 'Psalms 52:7', 'Psalms', 52, 7, '&nbsp;”ګورئ، دا هغه زورَور سپاهى دے چا چې د خُدائ په حفاظت يقين نۀ کولو، خو هغۀ په خپل ډېر مال دولت باندې يقين کولو، او نور هم زورَور شولو په شرارت کولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13730, 'Psalms 52:8', 'Psalms', 52, 8, '&nbsp;خو زۀ د زيتون د ونې په شان د خُدائ په کور کښې زرغون شوے يم، زۀ د خُدائ په ابدى مينه تر ابده پورې يقين لرم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13731, 'Psalms 52:9', 'Psalms', 52, 9, '&nbsp;تا چې څۀ کړى دى په هغې تر ابده ستا شُکر ادا کوم، ستا د پاکانو په وړاندې به زۀ ستا د نوم د ښۀ والى بيان کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13732, 'Psalms 53:1', 'Psalms', 53, 1, '&nbsp;کم عقلان په خپل زړۀ کښې وائى چې، ”خُدائ پاک نشته.“ دوئ په بدو اخته شول او بدعمله دى، تر دې چې يو هم نشته چې نېک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13733, 'Psalms 53:2', 'Psalms', 53, 2, '&nbsp;پاس د آسمانه خُدائ انسانانو ته ګورى، ګورى چې څوک شته چې وى هوښيار او د خُدائ لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13734, 'Psalms 53:3', 'Psalms', 53, 3, '&nbsp;خو ټول بې‌لارې شوى دى، او ټول يو شان خراب شوى دى. يو کس هم ښۀ نۀ کوى داسې يو هم نشته چې ښۀ کارونه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13735, 'Psalms 53:4', 'Psalms', 53, 4, '&nbsp;ولې څوک چې بدکارونه کوى دوئ نۀ پوهيږى. خو دوئ زما بنيادمان لکه د روټۍ لواړ تېروى، او هيڅکله هم دوئ د خُدائ پاک نه دُعا نۀ غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13736, 'Psalms 53:5', 'Psalms', 53, 5, '&nbsp;خو بيا هم داسې ويرېدل چې دې نه وړاندې کله هم داسې نۀ وُو يرېدلى. خُدائ پاک به ستا د دشمنانو هډُوکى تس نس کړى. او هغوئ به وشرميږى ځکه چې خُدائ پاک سپک کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13737, 'Psalms 53:6', 'Psalms', 53, 6, '&nbsp;څوک به راشى د صيون چې آزاد کړى بنى اِسرائيل، کله چې خُدائ پاک بيا آباد کړى خپل قوميان، يعقوب به خوشحالى وکړى او بنى اِسرائيل به خوشحاله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13738, 'Psalms 54:1', 'Psalms', 54, 1, '&nbsp;په خپل نوم سره دې ما ته خلاصون راکړه خُدايه، په خپل قدرت سره دې زما بې‌ګناهى ثابته کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13739, 'Psalms 54:2', 'Psalms', 54, 2, '&nbsp;دُعا زما واوره، اے پاکه خُدايه، د خولې خبرې زما واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13740, 'Psalms 54:3', 'Psalms', 54, 3, '&nbsp;پردى خلق په ما حملې کوى او ظالمان زما د مرګ کوشش کوى، او هغوئ د خُدائ پاک پرواه نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13741, 'Psalms 54:4', 'Psalms', 54, 4, '&nbsp;خو بې‌شکه خُدائ زما مددګار دے، او مالِک خُدائ په خپله ما ژوندے ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13742, 'Psalms 54:5', 'Psalms', 54, 5, '&nbsp;زما دشمنان دې په خپلو بدو کښې په خپله راګېر شى، او خپله وفادارى دې وښايه او دوئ تباه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13743, 'Psalms 54:6', 'Psalms', 54, 6, '&nbsp;زۀ به د زړۀ نه تا ته نذرانې پېش کړم، ځکه چې ستا نوم خوږ دے زۀ به ستا د نوم ثناء صِفت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13744, 'Psalms 54:7', 'Psalms', 54, 7, '&nbsp;بې‌شکه چې زۀ تا د ټولو مصيبتونو نه بچ کړم، او زۀ د خپلو دشمنانو شکست په خپلو سترګو باندې وينم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13745, 'Psalms 55:1', 'Psalms', 55, 1, '&nbsp;اے پاکه خُدايه، واوره سوال زما، ځان مۀ غلے کوه په سوال زارۍ زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13746, 'Psalms 55:2', 'Psalms', 55, 2, '&nbsp;جواب راکړه او واوره زما. خپلو پرېشانو ډېر زورَولے يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13747, 'Psalms 55:3', 'Psalms', 55, 3, '&nbsp;زما دشمنان ما يره وى، او ښکاره دهمکيانې راکوى، او په خپل قهر کښې دوئ زما نه نفرت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13748, 'Psalms 55:4', 'Psalms', 55, 4, '&nbsp;په سينه کښې د يرې نه درزيږى زړۀ زما، او د مرګ يرې زۀ راګېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13749, 'Psalms 55:5', 'Psalms', 55, 5, '&nbsp;يرې يم نيولے په لړزان يم، زۀ يرې او رپېدلو راخستے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13750, 'Psalms 55:6', 'Psalms', 55, 6, '&nbsp;کاش چې زما د ګوګوشتکو په شان وزرې وے، زۀ به په هوا کښې الوتلے او په آرام به وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13751, 'Psalms 55:7', 'Psalms', 55, 7, '&nbsp;زۀ به په هوا کښې الوتلے د دې ځايه وے، زۀ به په صحرا کښې اوسېدلے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13752, 'Psalms 55:8', 'Psalms', 55, 8, '&nbsp;ما به ځان دپاره په تېزۍ سره د پناه ځائ لټولے وے ترڅو چې زۀ دې سختو هواګانو طوفانونو نه امان کښې وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13753, 'Psalms 55:9', 'Psalms', 55, 9, '&nbsp;اے مالِکه خُدايه د بدکارو خبرې ګډې وډې کړه، ځکه زۀ په ښار کښې وينمه ظلم او جنګونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13754, 'Psalms 55:10', 'Psalms', 55, 10, '&nbsp;د حمله کوونکو خلاف يې شپه او ورځ د دېوالونو نه ګشت کيږى، خو حقيقى خطره هغه بدعملى ده کومه چې په ښار کښې دننه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13755, 'Psalms 55:11', 'Psalms', 55, 11, '&nbsp;تباهى يې د ښار په مينځ کښې ده، ډکې دى کوڅې د ظلم او دوکې نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13756, 'Psalms 55:12', 'Psalms', 55, 12, '&nbsp;کۀ چرې دشمن کوله بې‌عزتى زما، نو دا به برداشت کړے وے ما، کۀ دشمن چرې پخپله راپاڅېدلے وے په خلاف زما، نو خپل ځان د هغوئ نه به پټ کړے وے ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13757, 'Psalms 55:13', 'Psalms', 55, 13, '&nbsp;خو دا تۀ يې او انسان يې لکه زما، او ملګرے او نزدې دوست يې زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13758, 'Psalms 55:14', 'Psalms', 55, 14, '&nbsp;مونږ به د يو بل سره ښې خوږې خبرې کولې، او د خُدائ د کور په ګڼه کښې به يو ځائ ګرځېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13759, 'Psalms 55:15', 'Psalms', 55, 15, '&nbsp;زما دشمنان دې ناګهانه مړۀ شى، هغوئ دې په قبر کښې ژوندى ورښخ شى، ځکه چې شرارت د دوئ په زړونو کښې وردننه شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13760, 'Psalms 55:16', 'Psalms', 55, 16, '&nbsp;خو زۀ به خُدائ پاک ته آواز وکړم، او مالِک خُدائ به بچ کړى ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13761, 'Psalms 55:17', 'Psalms', 55, 17, '&nbsp;سحر، غرمه او ماښام به زۀ هغۀ ته خپل فريادونه وړاندې کوم، او هغه به واورى آواز زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13762, 'Psalms 55:18', 'Psalms', 55, 18, '&nbsp;هغه به مې په حفاظت سره بچ کوى، د هغه جنګ نه کوم چې زما په خلاف وى، کۀ څۀ هم چې ډېر خلق زما په ضد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13763, 'Psalms 55:19', 'Psalms', 55, 19, '&nbsp;خُدائ پاک چې د ازل نه په تخت ناست دے، هغه به زما سوال واورى او هغوئ له به شکست ورکړى. کوم خلق چې خپلې لارې نۀ بدلوى، او د خُدائ پاک نه نۀ يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13764, 'Psalms 55:20', 'Psalms', 55, 20, '&nbsp;زما ملګرى په خپلو دوستانو باندې حمله کړې ده، او خپل لوظ يې مات کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13765, 'Psalms 55:21', 'Psalms', 55, 21, '&nbsp;د هغۀ خبرې خوږې پستې دى، خو د هغۀ په زړۀ کښې خبرې د نفرت دى. د هغۀ خبرې د تېلو په شان نرمې دى، خو دا د تېرو تُورو په شان غوڅونکې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13766, 'Psalms 55:22', 'Psalms', 55, 22, '&nbsp;خپل مشکلات مالِک خُدائ ته پرېږده، او هغه به ستا حفاظت وکړى، هغه صادقان نۀ پرېږدى چې شکست وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13767, 'Psalms 55:23', 'Psalms', 55, 23, '&nbsp;خو، اے پاکه خُدايه، تۀ په خپله د تباهۍ په کنده کښې وغورزوې شريران، په ځوانۍ کښې به مړۀ شى دوکه ماران او قاتلان. خو زۀ به لرم په تا باندې ايمان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13768, 'Psalms 56:1', 'Psalms', 56, 1, '&nbsp;اے پاکه خُدايه، په ما رحم وکړه، خلق راپسې شوى دى، ټوله ورځ دشمنان په ما باندې سختې حملې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13769, 'Psalms 56:2', 'Psalms', 56, 2, '&nbsp;زما دشمنان ټوله ورځ ما وهى. ډېر زيات دى مغروره څوک چې ما سره جنګ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13770, 'Psalms 56:3', 'Psalms', 56, 3, '&nbsp;خو کله چې زۀ وويرېږم، نو زۀ به په تا باندې توکل وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13771, 'Psalms 56:4', 'Psalms', 56, 4, '&nbsp;کومه وعده چې هغۀ کړې ده، زۀ د خُدائ پاک ثناء صِفت کوم. نو زۀ نۀ يرېږم ځکه چې په خُدائ باندې توکل کوم. نو فانى انسان به ما سره څۀ وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13772, 'Psalms 56:5', 'Psalms', 56, 5, '&nbsp;زما دشمنان ټوله ورځ زما خبرې بدلوى، هر وخت هغوئ زما خلاف منصوبې جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13773, 'Psalms 56:6', 'Psalms', 56, 6, '&nbsp;ټول راټول شوى دى او پټ ناست دى، په هر قدم کښې راپسې دى او زما د مرګ خواهش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13774, 'Psalms 56:7', 'Psalms', 56, 7, '&nbsp;چې په خپل شرارت کښې وتښتى دوئ مۀ پرېږدئ، اے پاکه خُدايه، په خپل قهر او غضب کښې دې دوئ ته شکست ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13775, 'Psalms 56:8', 'Psalms', 56, 8, '&nbsp;تۀ د ټولو تکليفونو نه خبر يې زما، اوښکې دې يو لوښى کښې راغونډې کړې دى زما، ټول د غم حساب دې په خپل کِتاب کښې ليکلے زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13776, 'Psalms 56:9', 'Psalms', 56, 9, '&nbsp;دشمنان به مې وتښتى چې په کومه ورځ تا ته آواز وکړم، خُدائ زما ملګرے دے زۀ په دې باندې پوهېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13777, 'Psalms 56:10', 'Psalms', 56, 10, '&nbsp;کومه وعده چې خُدائ پاک ما سره کړې ده په هغې زۀ د خُدائ ثناء صِفت کوم. او کومه وعده چې مالِک خُدائ کړې ده په هغې زۀ د خُدائ شُکر ګزار يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13778, 'Psalms 56:11', 'Psalms', 56, 11, '&nbsp;نو زۀ نۀ يرېږمه ځکه چې په خُدائ پاک باندې توکل کوم. نو فانى انسان به ما سره څۀ وکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13779, 'Psalms 56:12', 'Psalms', 56, 12, '&nbsp;اے پاکه خُدايه، زۀ به تا سره د نذرانې وعده خپله سر ته رسوم، زۀ به تا ته د شکرانې نذرانې پېش کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13780, 'Psalms 56:13', 'Psalms', 56, 13, '&nbsp;تا زۀ د مرګ نه خلاص کړم. تا په خپله زۀ د تيندک خوړلو نه وساتلم، چې زۀ د ژوند په نُور کښې د خُدائ په حضور کښې وګرځم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13781, 'Psalms 57:1', 'Psalms', 57, 1, '&nbsp;رحم په ما وکړه، پاکه خُدايه، رحم غواړم، او تا له درځمه او زۀ ستا نه امان غواړم. ستا د وزرو په سورى کښې پناه غواړم ترڅو چې خطرناک طوفان تير شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13782, 'Psalms 57:2', 'Psalms', 57, 2, '&nbsp;زۀ خو خُدائ تعالىٰ ته سوال زارى کوم، کوم خُدائ پاک چې خپل مقصد زما دپاره سر ته رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13783, 'Psalms 57:3', 'Psalms', 57, 3, '&nbsp;هغه به زما د خلاصون دپاره د آسمان نه مدد راولېږى، او څوک چې ما ګېرول غواړى هغوئ به شرمنده کړى. خُدائ پاک دې ما ته خپله ابدى مينه او وفادارى وښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13784, 'Psalms 57:4', 'Psalms', 57, 4, '&nbsp;د يروونکو زمرو په مينځ کښې راګېر شوے يم، کوم چې د بنيادم غوښو خوړلو ته اوږے ناست وى، او د چا غاښونه چې د نېزو او غشو په شان وى او ژبې يې تېرې تُورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13785, 'Psalms 57:5', 'Psalms', 57, 5, '&nbsp;پاکه خُدايه، خپل عظمت دې په آسمانونو کښې څرګند کړه، او خپل جلال دې په ټوله زمکه باندې وځلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13786, 'Psalms 57:6', 'Psalms', 57, 6, '&nbsp;زما دشمنانو ما ته دامونه خوارۀ کړى دى، زۀ د خپلې پرېشانۍ په وجه ستړے شوے يم. زما په لار کښې دوئ کنده جوړه کړې ده. خو په خپله هم دوئ په کښې غورزېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13787, 'Psalms 57:7', 'Psalms', 57, 7, '&nbsp;زما زړۀ مطمئن دے زړۀ مې په تا مطمئن دے پاکه خُدايه، زۀ به هر وخت په سرود کښې ستا ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13788, 'Psalms 57:8', 'Psalms', 57, 8, '&nbsp;زما زړګيه پاڅه، زما سريندې او ربابه پاڅه، زۀ د سحر سباون په ثناء او صِفت راپاڅوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13789, 'Psalms 57:9', 'Psalms', 57, 9, '&nbsp;اے مالِکه خُدايه، زۀ به ستا شکريه په ټولو خلقو کښې ادا کړم، زۀ به ټولو قومونو کښې ستا صِفت بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13790, 'Psalms 57:10', 'Psalms', 57, 10, '&nbsp;ستا ابدى مينه آسمانونو ته رسيږى، هم ستا وفادارى آسمانونو سره لګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13791, 'Psalms 57:11', 'Psalms', 57, 11, '&nbsp;پاکه خُدايه، خپل عظمت دې په آسمانونو کښې څرګند کړه، او جلال دې په ټوله زمکه باندې وځلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13792, 'Psalms 58:1', 'Psalms', 58, 1, '&nbsp;بادشاهانو تاسو کله هم په رښتيا ښې فېصلې کړې دى څۀ؟ تاسو د خلقو عدالت په اِنصاف کوئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13793, 'Psalms 58:2', 'Psalms', 58, 2, '&nbsp;نه بلکې تاسو په زړونو کښې د بې‌اِنصافۍ منصوبې جوړَوئ، او تاسو په دُنيا کښې شرارت خوروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13794, 'Psalms 58:3', 'Psalms', 58, 3, '&nbsp;د پېدا کېدو نه وړاندې شريران خو بې‌لارې دى، او د مور نه دروغژن پېدا شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13795, 'Psalms 58:4', 'Psalms', 58, 4, '&nbsp;دوئ لکه د مار په شان زهريله خبرې کوى، دوئ لکه د کُوڼ کوبرا په شان غوږونه په ځان راړولى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13796, 'Psalms 58:5', 'Psalms', 58, 5, '&nbsp;د پاړو د شپيلۍ آواز نۀ اورى، کۀ هر څومره پاړو ښۀ شپيلۍ ورته غږوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13797, 'Psalms 58:6', 'Psalms', 58, 6, '&nbsp;د دوئ غاښونه مات کړه، پاکه خُدايه، د دې زمرو ژامنې ماتې کړه، مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13798, 'Psalms 58:7', 'Psalms', 58, 7, '&nbsp;لکه په خُشکه زمکه کښې چې اوبۀ ورکيږى دغه شان دې دوئ ورک شى، او کله چې هغوئ ليندې راکاږى د دوئ غشى دې په خپله مات شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13799, 'Psalms 58:8', 'Psalms', 58, 8, '&nbsp;هغوئ دې لکه د ګوجى په شان په خپله ويلى شى، لکه څنګه چې مړ ماشوم رڼا ليدلې نۀ وى دوئ دې داسې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13800, 'Psalms 58:9', 'Psalms', 58, 9, '&nbsp;خُدائ به ډېر زر ورله واړۀ زاړۀ ټول ختم کړى، لکه د ازغو اور چې د لوښى د ګرمېدو نه وړاندې ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');